<section class="section"><h2>Rendimiento por empleado</h2><p>Porcentaje de solicitudes finalizadas sobre las asignadas actualmente.</p><div class="tabla-scroll"><table><thead><tr><th>Empleado</th><th>Asignadas</th><th>Finalizadas</th><th>Porcentaje</th></tr></thead><tbody><?php foreach($empleados as $f): $porcentaje=$f['total']?round(100*$f['finalizadas']/$f['total'],1):0; ?><tr><td><?=h($f['nombre'])?></td><td><?=h($f['total'])?></td><td><?=h($f['finalizadas'])?></td><td><?=h($porcentaje)?>%</td></tr><?php endforeach; ?></tbody></table></div><div class="grafico" data-grafico="<?=h(json_encode(array_map(fn($f)=>['nombre'=>$f['nombre'],'total'=>(int)$f['finalizadas']],$empleados),JSON_UNESCAPED_UNICODE))?>"></div></section><script src="../assets/js/graficos.js"></script><?php fin(); ?>
